INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(21201, 'Joel 2:5', 'Joel', 2, 5, '&nbsp;د جنګى ګاډو د شور په شان هغوئ د غرونو په څوکو په ټوپونو تېريږى، او داسې ټسار کوى لکه کله چې اور ګياه سوزوى او يا لکه چې طاقتور فوج جنګ ته روان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21202, 'Joel 2:6', 'Joel', 2, 6, '&nbsp;د هغوئ په نظر کښې قومونه يره کښې دى، او د هر چا مخ د يرې نه زېړ دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21203, 'Joel 2:7', 'Joel', 2, 7, '&nbsp;هغوئ لکه د جنګيالو په شان حمله کوى، او د فوجيانو په شان په دېوالونو ورخېژى. هغوئ ټول په قطار کښې سيدها ځى، او د خپلې لارې نه اخوا ديخوا نۀ اوړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21204, 'Joel 2:8', 'Joel', 2, 8, '&nbsp;هغوئ يو بل له ديکې نۀ ورکوى، هر يو په خپله لاره نېغ ځى. او هغوئ د صفونو په صورت کښې د دشمن په مورچو ورننوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21205, 'Joel 2:9', 'Joel', 2, 9, '&nbsp;هغوئ په ښار باندې حملې دپاره ورغر وهى، او په دېوالونو يې په منډه وراوړى. هغوئ کورونو ته وراوړى او په کړکيانو باندې لکه د غلو په شان ورننوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21206, 'Joel 2:10', 'Joel', 2, 10, '&nbsp;هغوئ چې وړاندې ځى زمکه خوځيږى، آسمان لړزيږى، نمر او سپوږمۍ تيارۀ شى، او ستورى نور نۀ ‎ځليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21207, 'Joel 2:11', 'Joel', 2, 11, '&nbsp;مالِک خُدائ د خپل لښکر نه وړاندې لکه د تندر ګړزيږى. د هغۀ لښکر د شمېر نه بهر دے، او هغوئ طاقتور دى څوک چې د هغۀ حکم منى. د مالِک خُدائ د قيامت ورځ عظيمه، او سخته يروونکى ده. څوک دا برداشت کولے شى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21208, 'Joel 2:12', 'Joel', 2, 12, '&nbsp;مالِک خُدائ فرمائى چې، ”اوس هم تاسو سره موقع شته چې خپل ټول زړۀ سره ما ته په روژه نيولو، په ژړا او ماتم کولو سره راوګرځئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21209, 'Joel 2:13', 'Joel', 2, 13, '&nbsp;د خپل خفګان دپاره خپلې جامې مۀ شلوئ خو د هغې په ځائ خپل زړونه وشلوئ.“ مالِک خُدائ خپل خُدائ پاک ته راوګرځئ، ځکه چې هغه رحمان او رحيم دے، هغه زر نۀ غصه کيږى او د هغۀ مينه نۀ ختمېدونکى ده، او هغه دا غواړى چې معافى وکړى او سزا ورنۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21210, 'Joel 2:14', 'Joel', 2, 14, '&nbsp;چا ته پته ده، کېدے شى چې هغه بدل شى او زړۀ يې نرم شى او د لعنت په ځائ برکت درکړى. او تاسو لکه د مخکښې په شان د غلې او د ميو نذرانې مالِک خُدائ خپل خُدائ پاک ته پېش کړے شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21211, 'Joel 2:15', 'Joel', 2, 15, '&nbsp;په صيون کښې بيګل وغږوئ، د مقدسې روژې اعلان وکړئ، او خلق مقدسې اجتماع له راوغواړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21212, 'Joel 2:16', 'Joel', 2, 16, '&nbsp;ټول خلق راغونډ کړئ، او غونډه مقدسه کړئ، مشران، ماشومان او واړۀ ماشومان راغونډ کړئ. ناوې او زلمے د خپلې خپلې کوټې نه راوغواړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21213, 'Joel 2:17', 'Joel', 2, 17, '&nbsp;هغه اِمامان چې د مالِک خُدائ په حضور کښې خِدمت کوى، هغوئ دې د خُدائ پاک د کور د ډيوډۍ او د قربان‌ګاه په مينځ کښې ودريږى او ژړا دې وکړى. هغوئ دې داسې دُعا وغواړى، ”اے مالِکه خُدايه خپل خلق بچ کړه. خپل خاص ميراث مۀ د خندا کوه. هغوئ مۀ پرېږده چې بې‌ايمانه غېر مُلکيان ورپورې ټوقې وکړى څوک چې دا وائى، د بنى اِسرائيلو خُدائ پاک هغوئ پرېښودى دى څۀ؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21214, 'Joel 2:18', 'Joel', 2, 18, '&nbsp;نو بيا به مالِک خُدائ په خپل مُلک غېرت وکړى، او په خپلو خلقو باندې به مهربان شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21215, 'Joel 2:19', 'Joel', 2, 19, '&nbsp;مالِک خُدائ به هغوئ ته جواب ورکړى چې، ”ګورئ، زۀ تاسو له دومره غله دانه، نوى مے او د زيتُونو تېل درکوم چې ښۀ ډېر وى او پرې ماړۀ شئ، زۀ به بيا هيڅکله تاسو د نورو قومونو د خندا نۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21216, 'Joel 2:20', 'Joel', 2, 20, '&nbsp;زۀ به ستاسو نه د شمال ټول فوجيان لرې وشړم، او هغوئ به زۀ خوشى صحرا او وران مُلک ته وشړم. او د هغوئ وړومبۍ دستې به مشرقى سمندر ته او وروستۍ به يې مغربى سمندر ته وغورزوم. او د هغوئ سخا شوى لاشونو نه به بدبوئ خېژى او په هر طرف به خوريږى. يقيناً چې مالِک خُدائ غټ کارونه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21217, 'Joel 2:21', 'Joel', 2, 21, '&nbsp;اے زمکې، مۀ يرېږه، خوشحالى وکړه او خوشحاله اوسه، يقيناً چې مالِک خُدائ غټ کارونه کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21218, 'Joel 2:22', 'Joel', 2, 22, '&nbsp;اے ځنګلى ځناورو، مۀ يرېږئ. ځکه چې د صحرا د څرن زمکه راشنه کيږى. ونې به دوباره د مېوو نه ډکې شى، بيا به د اينځرو او د انګورو بوټى ښۀ ډېر ډک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21219, 'Joel 2:23', 'Joel', 2, 23, '&nbsp;اے د يروشلم خلقو خوشحالى وکړئ. په مالِک خُدائ خپل خُدائ پاک کښې خوشحالى وکړئ. ځکه چې هغۀ په وفادارۍ سره په تاسو د خزان بارانونه وکړل. هغه په تاسو د مخکښې په شان د خزان او د سپرلى دواړو ډېر بارانونه راوروى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21220, 'Joel 2:24', 'Joel', 2, 24, '&nbsp;درمندونه به بيا د غلې نه ډک شى، او چاټۍ به د نوؤ ميو او د زيتُونو د تېلو نه تر خولې خولې پورې ډکې شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21221, 'Joel 2:25', 'Joel', 2, 25, '&nbsp;مالِک خُدائ فرمائى چې، ”زۀ به تاسو ته د نقصان شوى فصل تاوان درکړم کوم چې د قحطۍ مُلخانو، غټو مُلخانو، وړو مُلخانو او نورو مُلخانو خوړلى وُو. دا زما لوئ لښکر وو چې ستاسو خلاف مې درلېږلے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21222, 'Joel 2:26', 'Joel', 2, 26, '&nbsp;تاسو سره به د خوړلو دپاره هر څۀ ډېر تېر وى ترڅو چې تاسو ښۀ ماړۀ شئ، او تاسو به د مالِک خُدائ خپل خُدائ پاک د نوم شُکر ګزارى وکړئ، چا چې ستاسو دپاره معجزې کړې دى. نو بيا به هيڅکله زما خلق ونۀ شرميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21223, 'Joel 2:27', 'Joel', 2, 27, '&nbsp;نو بيا به تاسو پوهه شئ چې زۀ د خپلو خلقو بنى اِسرائيلو په مينځ کښې يم، او دا چې زۀ مالِک خُدائ ستاسو خُدائ پاک يم او زما نه بغېر بل څوک نشته. نو بيا به هيڅکله زما خلق ونۀ شرميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21224, 'Joel 2:28', 'Joel', 2, 28, '&nbsp;د دې ټولو کارونو کولو نه وروستو به زۀ خپل روح په ټولو خلقو نازل کړم. ستاسو زامن او لوڼه به نبوت کوى، ستا مشران به خوبونه وينى، او ستاسو ځوانان به رويا ګانې وينى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21225, 'Joel 2:29', 'Joel', 2, 29, '&nbsp;په دې ورځو کښې به زۀ هم په نوکرانو سړو او ښځو دواړو خپل روح نازل کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21226, 'Joel 2:30', 'Joel', 2, 30, '&nbsp;زۀ به په آسمانونو او زمکه کښې حېرانونکى نښې يعنې وينه، اور او د لوګى برجۍ ښکاره کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21227, 'Joel 2:31', 'Joel', 2, 31, '&nbsp;نمر به تور شى، او سپوږمۍ به لکه د وينو تکه سره شى مخکښې د دې نه چې د مالِک خُدائ د قيامت هغه لويه او هيبتناکه ورځ راورسيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21228, 'Joel 2:32', 'Joel', 2, 32, '&nbsp;خو هر څوک چې د مالِک خُدائ په نوم مدد وغواړى هغه به بچ شى. او څۀ به په يروشلم کښې د صيون د غرۀ نه وتښتى، لکه څنګه چې مالِک خُدائ فرمائيلى دى، او هغوئ به په بچ شوو کسانو کښې وى څوک چې مالِک خُدائ راغوښتى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21229, 'Joel 3:1', 'Joel', 3, 1, '&nbsp;نو ګورئ، په هغه ورځو او په هغه وخت کښې، کله چې زۀ د يهوداه او يروشلم قسمتونه بحال کړم،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21230, 'Joel 3:2', 'Joel', 3, 2, '&nbsp;زۀ به ټول قومونه رايوځائ کړم او هغوئ به لاندې د يهوسفط وادۍ ته راولم. هلته به زۀ د هغوئ خلاف عدالت شروع کړم، د خپل ميراث يعنې د خپلو خلقو بنى اِسرائيلو په خاطر، ځکه چې هغوئ زما خلق د قومونو په مينځ کښې خوارۀ وارۀ کړى دى او زما مُلک يې په خپل مينځ کښې تقسيم کړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21231, 'Joel 3:3', 'Joel', 3, 3, '&nbsp;هغوئ زما په غوره شوو خلقو په خپلو کښې پچه واچوله. او هغوئ د کنجرو حاصلولو دپاره هلکان خرڅ کړل، او د ميو څښلو دپاره يې پېغلې جينکۍ خرڅې کړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21232, 'Joel 3:4', 'Joel', 3, 4, '&nbsp;اے د صور، او صيدا او د فلستيه ټولو علاقو، اوس تاسو سره زما خلاف څۀ دى؟ ولې تاسو ما نه د هغه څۀ بدل اخلئ چې ما کړى دى؟ کۀ تاسو داسې کوئ، زۀ به په تېزۍ او تُندۍ سره په تاسو هغه څۀ وکړم، څۀ چې تاسو کړى وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21233, 'Joel 3:5', 'Joel', 3, 5, '&nbsp;ځکه چې تاسو زما سپين زر او سرۀ زر واخستل او زما قيمتى خزانې مو خپلو مندرونو ته يوړې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21234, 'Joel 3:6', 'Joel', 3, 6, '&nbsp;تاسو د يهوداه او د يروشلم خلق په يونانيانو خرڅ کړل او هغوئ دې د خپل مُلک نه لرى ولېږل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21235, 'Joel 3:7', 'Joel', 3, 7, '&nbsp;ګوره زۀ به هغوئ د هغه ټولو ځايونو نه واپس راولم په کومو کښې چې تاسو خرڅ کړى دى، او زۀ به ستاسو په سرونو هغه څۀ راولم، کوم چې تاسو کړى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21236, 'Joel 3:8', 'Joel', 3, 8, '&nbsp;زۀ به ستاسو زامن او لوڼه د يهوداه په خلقو خرڅ کړم، او هغوئ به دوئ په لرې مُلک سبائيانو باندې خرڅ کړى. ما، مالِک خُدائ دا وفرمائيل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21237, 'Joel 3:9', 'Joel', 3, 9, '&nbsp;د قومونو په مينځ کښې دا اعلان وکړئ چې د جنګ دپاره تيار شئ، خپل ټول جنګيالى راوغواړئ، ټول جنګيالى نزدې راشئ او حمله وکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21238, 'Joel 3:10', 'Joel', 3, 10, '&nbsp;د خپلو قلبو د يوو نه په ټکولو تُورې جوړې کړئ او د خپلو بوټو د قينچيانو نه نېزې جوړې کړئ. کمزورے دې هم ووائى چې، ”زۀ تکړه يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21239, 'Joel 3:11', 'Joel', 3, 11, '&nbsp;اے ټولو قومونو د هر طرف نه زر تر زره راشئ، او په وادۍ کښې رايوځائ شئ. اے مالِکه خُدايه، اوس خپل لښکر راوغواړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21240, 'Joel 3:12', 'Joel', 3, 12, '&nbsp;قومونه دې راپاڅى، هغوئ دې د يهوسفط وادۍ ته لاړ شى. هلته به زۀ مالِک خُدائ ناست يم، چې د ګېرچاپېره ټولو قومونو عدالت وکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21241, 'Joel 3:13', 'Joel', 3, 13, '&nbsp;د هغوئ بدکارى ډېره لويه ده، لور وچلوئ ځکه چې فصل پوخ شوے دے. راشئ، انګور د پښو لاندې چخڼى کړئ ځکه چې د انګورو لنګرۍ ډکه ده. او د ذخيره کولو چاټۍ تر خولې ډکه ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21242, 'Joel 3:14', 'Joel', 3, 14, '&nbsp;په زرګونو زرګونو خلق د عدالت په وادۍ کښې دى. ځکه چې د عدالت په وادۍ کښې د مالِک خُدائ د قيامت ورځ رانزدې ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21243, 'Joel 3:15', 'Joel', 3, 15, '&nbsp;نمر او سپوږمۍ به تور شى، او ستورى به نور نۀ ځليږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21244, 'Joel 3:16', 'Joel', 3, 16, '&nbsp;مالِک خُدائ به د صيون نه وغړمبيږى، او د يروشلم نه به لکه د زمرى وغوريږى، آسمان او زمکه به ولړزيږى. خو مالِک خُدائ به د خپلو خلقو بنى اِسرائيلو دپاره د پناه ځائ او مضبوطه قلعه وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21245, 'Joel 3:17', 'Joel', 3, 17, '&nbsp;”نو بيا به تاسو ته پته ولګى چې زۀ، مالِک خُدائ ستاسو خُدائ پاک، په خپل مقدس غر صيون کښې اوسېږم. يروشلم به مقدس وى، او د پردى وطن لښکر به بيا هيڅکله هغه فتح نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21246, 'Joel 3:18', 'Joel', 3, 18, '&nbsp;په هغه ورځ به د غرونو نه نوى مے څڅيږى، او غونډو نه به پئ بهيږى، او د يهوداه ټولو ولو کښې به ډيرې اوبۀ روانې وى، او د مالِک خُدائ د کور نه به يوه چينه بهيږى چې د کيکر وادى به اوبۀ کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21247, 'Joel 3:19', 'Joel', 3, 19, '&nbsp;خو مِصر به وران ويجاړ شى، او ادوم به بيابان شى، ځکه چې هغوئ د يهوداه په خلقو ظلم وکړو، او هم د هغوئ په خپل مُلک کښې يې بې‌ګناه خلق ووژل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21248, 'Joel 3:20', 'Joel', 3, 20, '&nbsp;خو يهوداه به د تل دپاره آباد وى، او يروشلم به تر ټولو نسلونو قائم پاتې شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21249, 'Joel 3:21', 'Joel', 3, 21, '&nbsp;زۀ به د هغوئ د قتلونو بدل اخلم کوم چې تر اوسه پورې ما نۀ دے اخستے. ځکه چې مالِک خُدائ په صيون کښې اوسيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21250, 'Amos 1:1', 'Amos', 1, 1, '&nbsp;د عاموس پېغام، چې د تقوع ښار يو شپون وو. دا هغه پېغام دے څۀ چې هغۀ د زلزلې نه دوه کاله مخکښې د اِسرائيل په حقله په رويا کښې وليدل، کله چې عُزياه د يهوداه بادشاه وو او يربعام د يهوآس زوئ د اِسرائيل بادشاه وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21251, 'Amos 1:2', 'Amos', 1, 2, '&nbsp;هغۀ وفرمائيل، ”مالِک خُدائ د صيون نه غړمبيږى، او د يروشلم نه غوريږى. د شپونکو د څرن ځايونه به اوچ شى، او د کرمل د غرۀ په سر واښۀ به مړاوے شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21252, 'Amos 1:3', 'Amos', 1, 3, '&nbsp;مالِک خُدائ داسې فرمائى، ”د دمشق خلقو بار بار ګناه کړې ده، نو زۀ به هغوئ د سزا نه بغېر پرې نۀ ږدم. هغوئ زما خلق په جِلعاد کښې وهلى دى داسې لکه په تريشر چې غله دانه ټکولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21253, 'Amos 1:4', 'Amos', 1, 4, '&nbsp;نو زۀ به د حِزائيل په شاهى محل اور نازل کړم او دا به د بِن‌حدد قلعه ګانې وسوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21254, 'Amos 1:5', 'Amos', 1, 5, '&nbsp;زۀ به د دمشق دروازې ماتې کړم او د آون د وادۍ بادشاه چې په تخت ناست دے به ووژنم، زۀ به د بيت‌عدن بادشاه تباه کړم. د آرام خلق به د قير مُلک ته جلاوطن شى،“ مالِک خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21255, 'Amos 1:6', 'Amos', 1, 6, '&nbsp;مالِک خُدائ داسې فرمائى، ”د غزه خلقو بار بار ګناه کړې ده، نو زۀ به هغوئ د سزا نه بغېر پرې نۀ ږدم. ځکه چې هغوئ ټوله علاقه جلاوطن کړه او ادوم باندې يې خرڅه کړه،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21256, 'Amos 1:7', 'Amos', 1, 7, '&nbsp;نو زۀ به د غزه په دېوالونو اور نازل کړم، او هغه به د دې قلعه ګانې وسوزوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21257, 'Amos 1:8', 'Amos', 1, 8, '&nbsp;زۀ به د اشدود خلق وژنم او د اسقلون بادشاه به تباه کړم. بيا به زۀ په عقرون حمله وکړم او يو څو فلستيان چې ژوندى پاتې دى به هم مړۀ شى،“ دا د مالِک قادر مطلق خُدائ فرمان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21258, 'Amos 1:9', 'Amos', 1, 9, '&nbsp;مالِک خُدائ داسې فرمائى، ”د صور خلقو بار بار ګناه کړې ده، نو زۀ به هغوئ د سزا نه بغېر پرې نۀ ږدم. ځکه چې هغوئ د بنى اِسرائيلو سره د ورورولۍ د لوظ لحاظ ونۀ کړو بلکې ټوله علاقه يې جلاوطن کړه او په ادوم يې خرڅه کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21259, 'Amos 1:10', 'Amos', 1, 10, '&nbsp;نو زۀ به د صور په دېوالونو اور رانازل کړم او دا به د هغې ټولې قلعه ګانې وسوزوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21260, 'Amos 1:11', 'Amos', 1, 11, '&nbsp;مالِک خُدائ داسې فرمائى، ”د ادوم خلقو بار بار ګناه کړې ده، نو زۀ به هغوئ د سزا نه بغېر پرې نۀ ږدم. ځکه چې هغوئ خپلو وروڼو بنى اِسرائيلو پسې تُوره په لاس منډې وهلې او په هغوئ يې هيڅ رحم نۀ کولو. او خپله غصه يې جارى وساتله، او غصه يې د قابو نه بهر کېده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21261, 'Amos 1:12', 'Amos', 1, 12, '&nbsp;نو زۀ به په تيمان اور نازل کړم او دا به د بُصره قلعه ګانې تباه کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21262, 'Amos 1:13', 'Amos', 1, 13, '&nbsp;مالِک خُدائ داسې فرمائى، ”د عمون خلقو بار بار ګناه کړې ده، نو زۀ به هغوئ د سزا نه بغېر پرې نۀ ږدم. ځکه چې هغوئ د جِلعاد د اُميدوارو ښځو خيټې وڅيرلې د دې دپاره چې خپل سرحدونه لوئ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21263, 'Amos 1:14', 'Amos', 1, 14, '&nbsp;نو زۀ به د ربه په دېوالونو اور نازل کړم، او دا به د هغې ټولې قلعه ګانې وسوزوى. د جنګ په ورځ به د جنګ دغه شان چغې اورېدے شى، لکه د طوفان په ورځ چې تېزه سيلۍ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21264, 'Amos 1:15', 'Amos', 1, 15, '&nbsp;د هغوئ بادشاه به خپلو آفسرانو سره يو ځائ جلاوطن شى،“ دا د مالِک خُدائ فرمان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21265, 'Amos 2:1', 'Amos', 2, 1, '&nbsp;مالِک خُدائ داسې فرمائى، ”د موآب خلقو بار بار ګناه کړې ده، او زۀ به هغوئ د سزا نه بغېر پرې نۀ ږدم. ځکه چې هغوئ د ادوم د بادشاه هډُوکى وسوزول او ايرې يې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21266, 'Amos 2:2', 'Amos', 2, 2, '&nbsp;نو زۀ به په موآب اور نازل کړم، دا به د قريوت قلعه ګانې وسوزوى. څنګه چې د جنګ لويه اله ګوله شى او بيګل وغږيږى نو موآب به د جنګ په تاو کښې هلاک شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21267, 'Amos 2:3', 'Amos', 2, 3, '&nbsp;زۀ به د موآب بادشاه سره د هغۀ د آفسرانو تباه کړم،“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21268, 'Amos 2:4', 'Amos', 2, 4, '&nbsp;مالِک خُدائ داسې فرمائى، ”د يهوداه خلقو بار بار ګناه کړې ده، نو زۀ به هغوئ د سزا نه بغېر پرې نۀ ږدم. ځکه چې هغوئ د مالِک خُدائ شريعت رد کړو او د هغۀ په حُکمونو يې عمل ونۀ کړو. ځکه چې هغوئ د دروغو خُدايانو بې‌لارې کړل، هغه خُدايانو چې د دوئ پلار نيکونو يې پيروى کوله.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21269, 'Amos 2:5', 'Amos', 2, 5, '&nbsp;نو زۀ به په يهوداه اور نازل کړم او دا به د يروشلم قلعه ګانې وسوزوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21270, 'Amos 2:6', 'Amos', 2, 6, '&nbsp;مالِک خُدائ داسې فرمائى، ”د بنى اِسرائيل خلقو بار بار ګناه کړې ده، نو زۀ به هغوئ د سزا نه بغېر پرې نۀ ږدم. ځکه چې هغوئ صادقان خلق په سپينو زرو او غريبانان په يو جوړ څپلو خرڅوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21271, 'Amos 2:7', 'Amos', 2, 7, '&nbsp;هغوئ د غريبانانو سرونه لکه د زمکې د خاورى په شان د پښو لاندې کوى او نۀ پرېږدى چې مظلومانو ته اِنصاف مِلاو شى. پلار او زوئ هم يوې ښځې سره څملى او زما د پاک نوم بې‌حرمتى کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21272, 'Amos 2:8', 'Amos', 2, 8, '&nbsp;هغوئ د هرې قربان‌ګاه په خوا کښې په هغه کپړو کښې چې په ضمانت کښې اخستے شوې وى څملى. د خپل خُدائ په کور کښې هغوئ په هغه پېسو مے څښى چې د بې‌اِنصافۍ د جرمانې په طور اخستلے شوې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21273, 'Amos 2:9', 'Amos', 2, 9, '&nbsp;خو زما خلقو وکتل چې ما اموريان تباه کړل، اګر کۀ هغوئ د دِيار په شان لوَړ او د څېړۍ په شان مضبوط وُو. ما بره نه د هغې مېوه او لاندې نه جرړې وويستلې او برباد مې کړل.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21274, 'Amos 2:10', 'Amos', 2, 10, '&nbsp;هم ما تاسو د مِصر نه راوويستلئ، او څلوېښت کاله مې په صحرا کښې ستاسو لارښودنه وکړه چې تاسو د اموريانو زمکه قبضه کړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21275, 'Amos 2:11', 'Amos', 2, 11, '&nbsp;هم ما ستاسو ځينې زامن پېغمبران جوړ کړل او څۀ ځوانان مې د خِدمت دپاره د نذير په حيثيت وقف کړل. ولې دا رښتيا نۀ دى زما خلقو بنى اِسرائيلو؟“ مالِک خُدائ داسې فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21276, 'Amos 2:12', 'Amos', 2, 12, '&nbsp;”خو تاسو د نذير په حيثيت په وقف شوو خِدمت کوونکو مے وڅښل او د هغوئ قَسم مو مات کړو او پېغمبرانو ته مو حکم وکړو چې، پېشګويانې مۀ کوئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21277, 'Amos 2:13', 'Amos', 2, 13, '&nbsp;نو بيا، زۀ به تاسو داسې دباؤ کړم لکه څنګه چې د غلې نه ډکه ګاډۍ دباؤ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21278, 'Amos 2:14', 'Amos', 2, 14, '&nbsp;نۀ به تېزه منډه وهونکى وتښتېدے شى، او نۀ به طاقتور کښې طاقت پاتې شى، او نۀ به جنګيالى خپل ژوند بچ کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21279, 'Amos 2:15', 'Amos', 2, 15, '&nbsp;نۀ به غشى ويشتونکى، نۀ به تېزه منډه وهونکى او نۀ به په آس سوارۀ خپل ژوند بچ کړے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21280, 'Amos 2:16', 'Amos', 2, 16, '&nbsp;په هغه ورځ به تکړه فوجيان هم بربنډ وتښتى،“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21281, 'Amos 3:1', 'Amos', 3, 1, '&nbsp;دا کلام واورئ چې مالِک خُدائ ستاسو خلاف فرمائى، اے بنى اِسرائيلو، دا د هغه ټولو قبيلو خلاف دے چې ما د مِصر نه بهر راويستى دى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21282, 'Amos 3:2', 'Amos', 3, 2, '&nbsp;”صرف تاسو يئ چې ما د زمکې په ټولو قومونو کښې خوښ کړى يئ، نو ځکه به زۀ تاسو ته ستاسو د ټولو ګناهونو په وجه سزا درکړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21283, 'Amos 3:3', 'Amos', 3, 3, '&nbsp;آيا دوه کسان يو ځائ سفر کولے شى ترڅو چې هغوئ داسې کولو باندې متفِق نۀ وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21284, 'Amos 3:4', 'Amos', 3, 4, '&nbsp;آيا زمرے په ځنګل کښې غړمبيږى کله چې د هغۀ ښکار نۀ وى؟ آيا هغه په خپل غار کښې غړمبيږى کله چې هغۀ څۀ نۀ وى نيولى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21285, 'Amos 3:5', 'Amos', 3, 5, '&nbsp;آيا يو مارغۀ په لټ کښې ګېرېدے شى کله چې ورته د ګېرېدو دپاره څۀ نۀ وى؟ آيا دام په زمکه په خپله بنديږى کله چې ښکار د ګېرېدو دپاره نۀ وى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21286, 'Amos 3:6', 'Amos', 3, 6, '&nbsp;کله چې په ښار کښې بيګل وغږيږى نو خلق نۀ يريږى؟ کله چې يو ښار باندې افت راشى آيا دا مالِک خُدائ نۀ وى راوستے؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21287, 'Amos 3:7', 'Amos', 3, 7, '&nbsp;يقيناً چې قادر مطلق خُدائ هيڅ نۀ کوى ترڅو چې خپله منصوبه خِدمت کوونکو پېغمبرانو ته څرګنده نۀ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21288, 'Amos 3:8', 'Amos', 3, 8, '&nbsp;خو اوس زمرے په غړمبېدو دے نو څوک به نۀ يريږى؟ اوس خو قادر مطلق خُدائ خپل کلام وفرمائيلو، نو څوک به د هغۀ د پېشګويۍ ورکولو نه اِنکار وکړى؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21289, 'Amos 3:9', 'Amos', 3, 9, '&nbsp;د اشدود قلعه ګانو ته او د مِصر قلعه ګانو ته اعلان وکړه چې، ”د سامريه په غرونو راغونډ شئ او وګورئ چې په دې ښار کښې څۀ کيږى. څومره لويه ګډوډى ده پکښې او څومره ظلم د هغې خلقو سره کيږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21290, 'Amos 3:10', 'Amos', 3, 10, '&nbsp;مالِک خُدائ فرمائى، ”هغوئ په دې نۀ پوهيږى چې صحيح کار څنګه وکړى. هغوئ خپلې قلعه ګانې د هغه مال نه ډکې کړې دى کوم چې په ظلم زياتې او غلا سره اخستے شوے دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21291, 'Amos 3:11', 'Amos', 3, 11, '&nbsp;نو ځکه قادر مطلق خُدائ ‏‏داسې فرمائى چې، ”دشمن به ستاسو وطن محاصره کړى او ستاسو پخې قلعې به راوغورزوى او ستاسو قلعې به لوټ کړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21292, 'Amos 3:12', 'Amos', 3, 12, '&nbsp;مالِک خُدائ دا فرمائى، ”لکه څنګه چې يو شپون د ازمرى د خولې نه د ګډې د پښې يو دوه هډوکى يا د غوږ يوه ټوکړه بچ کړى، نو دغسې به هغه بنى اِسرائيل چې په سامريه کښې اوسيږى هغوئ به دومره برباد شى او داسې به پاتې شى لکه چې د کټ يو بازو او د کُرسۍ يوه پښه باقى پاتې شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21293, 'Amos 3:13', 'Amos', 3, 13, '&nbsp;قادر مطلق خُدائ، ربُ الافواج دا فرمائى، ”واورئ، او د يعقوب د خاندان خلاف ګواهى ورکړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21294, 'Amos 3:14', 'Amos', 3, 14, '&nbsp;په کومه ورځ چې زۀ بنى اِسرائيلو له د ګناهونو سزا ورکوم، زۀ به د بيت‌ايل قربان‌ګاه تباه کړم. د هرې قربان‌ګاه ښکرونه به مات شى او په زمکه به راوغورزولے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21295, 'Amos 3:15', 'Amos', 3, 15, '&nbsp;زۀ به د اوړى کورونه او د ژمى کورونه دواړه تباه کړم. هغه کورونه چې د هاتى په غاښونو ښائسته کړے شوى دى هغه به تباه شى او دا محلونه به باقى پاتې نۀ شى،“ مالِک خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21296, 'Amos 4:1', 'Amos', 4, 1, '&nbsp;”ما ته غوږ ونيسئ، د سامريه په غرونو اے د بسن څربه غواګانو، تاسو هغه ښځې يئ چې په غريبانانو ظلم کوئ او ضرورتمند د پښو لاندې کوئ، او څوک چې خپلو خاوندانو ته همېشه وائى چې، مونږ له د څښلو دپاره مے راوړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21297, 'Amos 4:2', 'Amos', 4, 2, '&nbsp;قادر مطلق خُدائ په خپل پاکوالى قسم وکړو چې هغه وخت به يقيناً راشى چې تاسو ته به پوزو کښې کُنډې واچولے شى او په راښکلو به بوتلے شئ، تاسو هر يو کس به داسې راښکلے شئ لکه څنګه چې په کُنډه کښې کب راښکلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21298, 'Amos 4:3', 'Amos', 4, 3, '&nbsp;تاسو هر يو به په دېوالونو کښې د جوړو شوو لارو نه په زور وويستلے شئ، تاسو به بهر د حرمون شمال طرف ته وغورزولے شئ،“ مالِک خُدائ دا فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21299, 'Amos 4:4', 'Amos', 4, 4, '&nbsp;”نو بيا خو لاړ شئ او په بيت‌ايل کښې بُتانو ته قربانۍ پېش کړئ. په جِلجال کښې نافرمانۍ جارى ساتئ. هر سحر قربانى کوئ، او په هره درېمه ورځ خپله لسمه حِصه راوړئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(21300, 'Amos 4:5', 'Amos', 4, 5, '&nbsp;خمبيره روټۍ د شکرانې په طور پېش کړئ بيا په اوچت آواز د هغه قربانو اعلان وکړئ کومې چې تاسو په خپله خوښه کوئ. ځکه چې داسې کارونه کول تاسو بنى اِسرائيل ډېر خوښوئ،“ دا مالِک قادر مطلق خُدائ فرمائى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');